    // Print results
    if(info) {
        std::cout << info->name << std::endl;
        std::cout << info->age << std::endl;
        std::cout << info->citizenship << std::endl;
        free_student_info(info);
    } else {
        // std::cout << "Student not found or invalid credentials\n";
    }

    // Cleanup
    xmlCleanupParser();

    return 0;
}

