    result.key = (unsigned char*)malloc(16);  // AES-128 key size
    if (!result.iv || !result.key) {
        free(result.iv);
        free(result.key);
        return result;
    }

    // Generate random IV
    if (RAND_bytes(result.iv, AES_BLOCK_SIZE) != 1) {
