    av_reduce(&tbase, &smk->pts_inc, tbase, smk->pts_inc, (1UL<<31)-1);
    av_set_pts_info(st, 33, smk->pts_inc, tbase);

    for(i = 0; i < 7; i++) {
        smk->indexes[i] = -1;
